static void MSG_WriteChar (sizebuf_t* sb, int c) {
	assert((c >= -128) && (c <= 127));
	u8* buf = SZ_GetSpace(sb, 1);
	buf[0] = c;
}

static void MSG_WriteByte (sizebuf_t* sb, int c) {
	assert(c >= 0 && c <= 255);
	u8* buf = SZ_GetSpace (sb, 1);
	buf[0] = c;
}

static void MSG_WriteShort(sizebuf_t* sb, int c) {
	u8* buf = SZ_GetSpace(sb, 2);
	buf[0] = c & 0xff;
	buf[1] = c >> 8;
}

static void MSG_WriteLong(sizebuf_t* sb, int c) {
	u8* buf = SZ_GetSpace(sb, 4);
	buf[0] = c & 0xff;
	buf[1] = (c>>8) & 0xff;
	buf[2] = (c>>16) & 0xff;
	buf[3] = c>>24;
}

static void MSG_WriteFloat(sizebuf_t* sb, float f) {
	union {
		float	f;
		int	l;
	} dat;
	dat.f = f;
	dat.l = LittleLong(dat.l);
	SZ_Write(sb, &dat.l, 4);
}

static void MSG_WriteString(sizebuf_t* sb, char* s) {
	if (!s) {
		SZ_Write (sb, "", 1);
	} else {
		SZ_Write (sb, s, strlen(s) + 1);
	}
}

static void MSG_WriteCoord(sizebuf_t* sb, float f) {
	MSG_WriteShort(sb, (int)(f * 8));
}

static void MSG_WritePos(sizebuf_t* sb, vec3_t pos) {
	MSG_WriteShort(sb, (int)(pos[0] * 8));
	MSG_WriteShort(sb, (int)(pos[1] * 8));
	MSG_WriteShort(sb, (int)(pos[2] * 8));
}

static void MSG_WriteAngle(sizebuf_t* sb, float f) {
	MSG_WriteByte(sb, (int)(f*256/360) & 255);
}

static void MSG_WriteAngle16(sizebuf_t* sb, float f) {
	MSG_WriteShort (sb, ANGLE2SHORT(f));
}

static void MSG_WriteDeltaUsercmd (sizebuf_t* buf, usercmd_t* from, usercmd_t* cmd) {

	// send the movement message
	int bits = 0;
	if (cmd->angles[0] != from->angles[0]) {
		bits |= CM_ANGLE1;
	}
	if (cmd->angles[1] != from->angles[1]) {
		bits |= CM_ANGLE2;
	}
	if (cmd->angles[2] != from->angles[2]) {
		bits |= CM_ANGLE3;
	}
	if (cmd->forwardmove != from->forwardmove) {
		bits |= CM_FORWARD;
	}
	if (cmd->sidemove != from->sidemove) {
		bits |= CM_SIDE;
	}
	if (cmd->upmove != from->upmove) {
		bits |= CM_UP;
	}
	if (cmd->buttons != from->buttons) {
		bits |= CM_BUTTONS;
	}
	if (cmd->impulse != from->impulse) {
		bits |= CM_IMPULSE;
	}

	MSG_WriteByte(buf, bits);

	if (bits & CM_ANGLE1) {
		MSG_WriteShort(buf, cmd->angles[0]);
	}
	if (bits & CM_ANGLE2) {
		MSG_WriteShort(buf, cmd->angles[1]);
	}
	if (bits & CM_ANGLE3) {
		MSG_WriteShort(buf, cmd->angles[2]);
	}

	if (bits & CM_FORWARD) {
		MSG_WriteShort(buf, cmd->forwardmove);
	}
	if (bits & CM_SIDE) {
		MSG_WriteShort(buf, cmd->sidemove);
	}
	if (bits & CM_UP) {
		MSG_WriteShort(buf, cmd->upmove);
	}

 	if (bits & CM_BUTTONS) {
		MSG_WriteByte(buf, cmd->buttons);
	}
 	if (bits & CM_IMPULSE) {
		MSG_WriteByte(buf, cmd->impulse);
	}

	MSG_WriteByte(buf, cmd->msec);
	MSG_WriteByte(buf, cmd->lightlevel);
}

// Writes part of a packetentities message. Can delta from either a baseline or a previous packet_entity
static void MSG_WriteDeltaEntity(entity_state_t* from, entity_state_t* to, sizebuf_t* msg, bool force, bool newentity) {
	assert(to->number > 0 && to->number < MAX_EDICTS);

	// send an update
	int bits = 0;

	if (to->number >= 256) {
		bits |= U_NUMBER16;	// number8 is implicit otherwise
	}

	if (to->origin[0] != from->origin[0]) {
		bits |= U_ORIGIN1;
	}
	if (to->origin[1] != from->origin[1]) {
		bits |= U_ORIGIN2;
	}
	if (to->origin[2] != from->origin[2]) {
		bits |= U_ORIGIN3;
	}

	if (to->angles[0] != from->angles[0]) {
		bits |= U_ANGLE1;
	}
	if (to->angles[1] != from->angles[1]) {
		bits |= U_ANGLE2;
	}
	if (to->angles[2] != from->angles[2]) {
		bits |= U_ANGLE3;
	}

	if (to->skinnum != from->skinnum) {
		if ((unsigned)to->skinnum < 256) {
			bits |= U_SKIN8;
		}
		else if ((unsigned)to->skinnum < 0x10000) {
			bits |= U_SKIN16;
		}
		else {
			bits |= (U_SKIN8|U_SKIN16);
		}
	}

	if (to->frame != from->frame) {
		if (to->frame < 256) {
			bits |= U_FRAME8;
		} else {
			bits |= U_FRAME16;
		}
	}

	if (to->effects != from->effects) {
		if (to->effects < 256) {
			bits |= U_EFFECTS8;
		} else if (to->effects < 0x8000) {
			bits |= U_EFFECTS16;
		} else {
			bits |= U_EFFECTS8|U_EFFECTS16;
		}
	}

	if (to->renderfx != from->renderfx) {
		if (to->renderfx < 256) {
			bits |= U_RENDERFX8;
		} else if (to->renderfx < 0x8000) {
			bits |= U_RENDERFX16;
		} else {
			bits |= U_RENDERFX8|U_RENDERFX16;
		}
	}

	if (to->solid != from->solid) {
		bits |= U_SOLID;
	}

	// event is not delta compressed, just 0 compressed
	if (to->event) {
		bits |= U_EVENT;
	}

	if (to->modelindex != from->modelindex) {
		bits |= U_MODEL;
	}
	if (to->modelindex2 != from->modelindex2) {
		bits |= U_MODEL2;
	}
	if (to->modelindex3 != from->modelindex3) {
		bits |= U_MODEL3;
	}
	if (to->modelindex4 != from->modelindex4) {
		bits |= U_MODEL4;
	}

	if (to->sound != from->sound) {
		bits |= U_SOUND;
	}

	if (newentity || (to->renderfx & RF_BEAM)) {
		bits |= U_OLDORIGIN;
	}

	// write the message
	if (!bits && !force) {
		return;	// nothing to send!
	}

	if (bits & 0xff000000) {
		bits |= U_MOREBITS3 | U_MOREBITS2 | U_MOREBITS1;
	} else if (bits & 0x00ff0000) {
		bits |= U_MOREBITS2 | U_MOREBITS1;
	} else if (bits & 0x0000ff00) {
		bits |= U_MOREBITS1;
	}

	MSG_WriteByte(msg, bits&255);

	if (bits & 0xff000000) {
		MSG_WriteByte(msg, (bits>>8)&255);
		MSG_WriteByte(msg, (bits>>16)&255);
		MSG_WriteByte(msg, (bits>>24)&255);
	} else if (bits & 0x00ff0000) {
		MSG_WriteByte(msg, (bits>>8)&255);
		MSG_WriteByte(msg, (bits>>16)&255);
	} else if (bits & 0x0000ff00) {
		MSG_WriteByte(msg, (bits>>8)&255);
	}

	if (bits & U_NUMBER16) {
		MSG_WriteShort(msg, to->number);
	} else {
		MSG_WriteByte(msg, to->number);
	}

	if (bits & U_MODEL) {
		MSG_WriteByte(msg, to->modelindex);
	}
	if (bits & U_MODEL2) {
		MSG_WriteByte(msg, to->modelindex2);
	}
	if (bits & U_MODEL3) {
		MSG_WriteByte(msg, to->modelindex3);
	}
	if (bits & U_MODEL4) {
		MSG_WriteByte(msg, to->modelindex4);
	}

	if (bits & U_FRAME8) {
		MSG_WriteByte(msg, to->frame);
	}
	if (bits & U_FRAME16) {
		MSG_WriteShort (msg, to->frame);
	}

	// used for laser colors
	if ((bits & U_SKIN8) && (bits & U_SKIN16)) {
		MSG_WriteLong(msg, to->skinnum);
	} else if (bits & U_SKIN8) {
		MSG_WriteByte(msg, to->skinnum);
	} else if (bits & U_SKIN16) {
		MSG_WriteShort(msg, to->skinnum);
	}

	if ((bits & (U_EFFECTS8|U_EFFECTS16)) == (U_EFFECTS8|U_EFFECTS16)) {
		MSG_WriteLong(msg, to->effects);
	} else if (bits & U_EFFECTS8) {
		MSG_WriteByte(msg, to->effects);
	} else if (bits & U_EFFECTS16) {
		MSG_WriteShort(msg, to->effects);
	}

	if ((bits & (U_RENDERFX8|U_RENDERFX16)) == (U_RENDERFX8|U_RENDERFX16)) {
		MSG_WriteLong(msg, to->renderfx);
	} else if (bits & U_RENDERFX8) {
		MSG_WriteByte(msg, to->renderfx);
	} else if (bits & U_RENDERFX16) {
		MSG_WriteShort(msg, to->renderfx);
	}

	if (bits & U_ORIGIN1) {
		MSG_WriteCoord(msg, to->origin[0]);
	}
	if (bits & U_ORIGIN2) {
		MSG_WriteCoord(msg, to->origin[1]);
	}
	if (bits & U_ORIGIN3) {
		MSG_WriteCoord(msg, to->origin[2]);
	}

	if (bits & U_ANGLE1) {
		MSG_WriteAngle(msg, to->angles[0]);
	}
	if (bits & U_ANGLE2) {
		MSG_WriteAngle(msg, to->angles[1]);
	}
	if (bits & U_ANGLE3) {
		MSG_WriteAngle(msg, to->angles[2]);
	}

	if (bits & U_OLDORIGIN) {
		MSG_WriteCoord(msg, to->old_origin[0]);
		MSG_WriteCoord(msg, to->old_origin[1]);
		MSG_WriteCoord(msg, to->old_origin[2]);
	}

	if (bits & U_SOUND) {
		MSG_WriteByte(msg, to->sound);
	}
	if (bits & U_EVENT) {
		MSG_WriteByte(msg, to->event);
	}
	if (bits & U_SOLID) {
		MSG_WriteShort(msg, to->solid);
	}
}

static void MSG_WriteDir(sizebuf_t* sb, vec3_t dir) {
	if (!dir) {
		MSG_WriteByte(sb, 0);
		return;
	}

	float bestd = 0;
	int best = 0;
	for (int i = 0; i < NUMVERTEXNORMALS; i++) {
		float d = DotProduct(dir, bytedirs[i]);
		if (d > bestd) {
			bestd = d;
			best = i;
		}
	}
	MSG_WriteByte (sb, best);
}

static void MSG_BeginReading(sizebuf_t* msg) {
	msg->readcount = 0;
}

// returns -1 if no more characters are available
static int MSG_ReadChar(sizebuf_t* msg_read) {
	int c = -1;
	if (msg_read->readcount + 1 <= msg_read->cursize) {
		c = (signed char)msg_read->data[msg_read->readcount];
	}
	msg_read->readcount++;
	return c;
}

static int MSG_ReadByte(sizebuf_t* msg_read) {
	int	c = -1;
	if (msg_read->readcount + 1 <= msg_read->cursize) {
		c = (unsigned char)msg_read->data[msg_read->readcount];
	}
	msg_read->readcount++;
	return c;
}

static int MSG_ReadShort (sizebuf_t* msg_read) {
	int	c = - 1;
	if (msg_read->readcount+2 <= msg_read->cursize) {
		c = (short)(msg_read->data[msg_read->readcount] + (msg_read->data[msg_read->readcount+1]<<8));
	}
	msg_read->readcount += 2;
	return c;
}

static int MSG_ReadLong(sizebuf_t* msg_read) {
	int	c = -1;
	if (msg_read->readcount + 4 <= msg_read->cursize) {
		c = msg_read->data[msg_read->readcount]
			+ (msg_read->data[msg_read->readcount+1]<<8)
			+ (msg_read->data[msg_read->readcount+2]<<16)
			+ (msg_read->data[msg_read->readcount+3]<<24);
	}
	msg_read->readcount += 4;
	return c;
}

static char* MSG_ReadString(sizebuf_t* msg_read) {
	static char	string[2048];

	int l = 0;
	do {
		int c = MSG_ReadChar(msg_read);
		if (c == -1 || c == 0) {
			break;
		}
		string[l] = c;
		l++;
	} while (l < (int)sizeof(string) - 1);

	string[l] = 0;
	return string;
}

static char* MSG_ReadStringLine(sizebuf_t* msg_read) {
	static char	string[2048];

	int l = 0;
	do {
		int c = MSG_ReadChar (msg_read);
		if (c == -1 || c == 0 || c == '\n') {
			break;
		}
		string[l] = c;
		l++;
	} while (l < (int)sizeof(string) - 1);

	string[l] = 0;
	return string;
}

static float MSG_ReadCoord(sizebuf_t* msg_read) {
	return MSG_ReadShort(msg_read) * (1.0/8);
}

static void MSG_ReadPos(sizebuf_t* msg_read, vec3_t pos) {
	pos[0] = MSG_ReadShort(msg_read) * (1.0/8);
	pos[1] = MSG_ReadShort(msg_read) * (1.0/8);
	pos[2] = MSG_ReadShort(msg_read) * (1.0/8);
}

static float MSG_ReadAngle(sizebuf_t* msg_read) {
	return MSG_ReadChar(msg_read) * (360.0/256);
}

static float MSG_ReadAngle16 (sizebuf_t* msg_read) {
	return SHORT2ANGLE(MSG_ReadShort(msg_read));
}

static void MSG_ReadDeltaUsercmd(sizebuf_t* msg_read, usercmd_t* from, usercmd_t* move) {
	memcpy (move, from, sizeof(*move));
	int bits = MSG_ReadByte (msg_read);

	// read current angles
	if (bits & CM_ANGLE1) {
		move->angles[0] = MSG_ReadShort(msg_read);
	}
	if (bits & CM_ANGLE2) {
		move->angles[1] = MSG_ReadShort(msg_read);
	}
	if (bits & CM_ANGLE3) {
		move->angles[2] = MSG_ReadShort(msg_read);
	}

	// read movement
	if (bits & CM_FORWARD) {
		move->forwardmove = MSG_ReadShort(msg_read);
	}
	if (bits & CM_SIDE)
		move->sidemove = MSG_ReadShort(msg_read);
	if (bits & CM_UP)
		move->upmove = MSG_ReadShort(msg_read);

	// read buttons
	if (bits & CM_BUTTONS) {
		move->buttons = MSG_ReadByte(msg_read);
	}

	if (bits & CM_IMPULSE) {
		move->impulse = MSG_ReadByte(msg_read);
	}

	// read time to run command
	move->msec = MSG_ReadByte(msg_read);

	// read the light level
	move->lightlevel = MSG_ReadByte(msg_read);
}

static void MSG_ReadDir(sizebuf_t* sb, vec3_t dir) {
	int b = MSG_ReadByte(sb);
	assert(b < NUMVERTEXNORMALS);
	VectorCopy(bytedirs[b], dir);
}

