void CMod_LoadVisibility (lump_t *l)
{
	int		i;

	numvisibility = l->filelen;
	assert(l->filelen <= MAX_MAP_VISIBILITY);

	memcpy (map_visibility, cmod_base + l->fileofs, l->filelen);

	map_vis->numclusters = LittleLong (map_vis->numclusters);
	for (i=0 ; i<map_vis->numclusters ; i++)
	{
		map_vis->bitofs[i][0] = LittleLong (map_vis->bitofs[i][0]);
		map_vis->bitofs[i][1] = LittleLong (map_vis->bitofs[i][1]);
	}
}

void CMod_LoadEntityString (lump_t *l)
{
	numentitychars = l->filelen;
	assert(l->filelen <= MAX_MAP_ENTSTRING);
	memcpy (map_entitystring, cmod_base + l->fileofs, l->filelen);
}

static cmodel_t* CM_LoadMap(char* name, bool clientload, unsigned* checksum) {
	int				length;
	static unsigned	last_checksum;

	map_noareas = COM_GetCvar("map_noareas", "0", 0);

	if (!strcmp(map_name, name) && (clientload || !Cvar_VariableValue ("flushmap")) ) {
		*checksum = last_checksum;
		if (!clientload) {
			memset (portalopen, 0, sizeof(portalopen));
			FloodAreaConnections();
		}
		return &map_cmodels[0];	// still have the right version
	}

	// free old stuff
	numplanes = 0;
	numnodes = 0;
	numleafs = 0;
	numcmodels = 0;
	numvisibility = 0;
	numentitychars = 0;
	map_entitystring[0] = 0;
	map_name[0] = 0;

	if (!name || !name[0]) {
		numleafs = 1;
		numclusters = 1;
		numareas = 1;
		*checksum = 0;
		return &map_cmodels[0];
	}

	unsigned* buf = 0;
	length = FS_LoadFile(name, (void **)&buf);
	assert(buf);

	last_checksum = LittleLong(Com_BlockChecksum (buf, length));
	*checksum = last_checksum;

	dheader_t header = *(dheader_t*)buf;
	for (int i = 0; i < (int)sizeof(dheader_t) / 4; i++) {
		((int *)&header)[i] = LittleLong ( ((int *)&header)[i]);
	}

	assert(header.version == BSPVERSION);

	cmod_base = (u8*)buf;

	// load into heap
	CMod_LoadSurfaces (&header.lumps[LUMP_TEXINFO]);
	CMod_LoadLeafs (&header.lumps[LUMP_LEAFS]);
	CMod_LoadLeafBrushes (&header.lumps[LUMP_LEAFBRUSHES]);
	CMod_LoadPlanes (&header.lumps[LUMP_PLANES]);
	CMod_LoadBrushes (&header.lumps[LUMP_BRUSHES]);
	CMod_LoadBrushSides (&header.lumps[LUMP_BRUSHSIDES]);
	CMod_LoadSubmodels (&header.lumps[LUMP_MODELS]);
	CMod_LoadNodes (&header.lumps[LUMP_NODES]);
	CMod_LoadAreas (&header.lumps[LUMP_AREAS]);
	CMod_LoadAreaPortals (&header.lumps[LUMP_AREAPORTALS]);
	CMod_LoadVisibility (&header.lumps[LUMP_VISIBILITY]);
	CMod_LoadEntityString (&header.lumps[LUMP_ENTITIES]);

	FS_FreeFile (buf);

	CM_InitBoxHull ();

	memset (portalopen, 0, sizeof(portalopen));
	FloodAreaConnections ();

	strcpy (map_name, name);

	return &map_cmodels[0];
}

