// For proxy protecting
u8 COM_BlockSequenceCRCByte(u8 *base, int length, int sequence)
{
	int		n;
	u8	*p;
	int		x;
	u8 chkb[60 + 4];
	unsigned short crc;

	assert(sequence >= 0);

	p = chktbl + (sequence % (sizeof(chktbl) - 4));

	if (length > 60)
		length = 60;
	memcpy (chkb, base, length);

	chkb[length] = p[0];
	chkb[length+1] = p[1];
	chkb[length+2] = p[2];
	chkb[length+3] = p[3];

	length += 4;

	crc = CRC_Block(chkb, length);

	for (x=0, n=0; n<length; n++)
		x += chkb[n];

	crc = (crc ^ x) & 0xff;

	return crc;
}

// if a packfile directory differs from this, it is assumed to be hacked
// Full version
#define	PAK0_CHECKSUM	0x40e614e0
// Demo
//#define	PAK0_CHECKSUM	0xb2c6d7ea
// OEM
//#define	PAK0_CHECKSUM	0x78e135c

/*
=============================================================================

QUAKE FILESYSTEM

=============================================================================
*/


//
// in memory
//

typedef struct
{
	char	name[MAX_QPATH];
	int		filepos, filelen;
} packfile_t;

typedef struct pack_s
{
	char	filename[MAX_OSPATH];
	FILE	*handle;
	int		numfiles;
	packfile_t	*files;
} pack_t;

typedef struct searchpath_s
{
	char	filename[MAX_OSPATH];
	pack_t	*pack;		// only one of filename / pack will be used
	struct searchpath_s *next;
} searchpath_t;

searchpath_t	*fs_searchpaths;

// All of Quake's data access is through a hierchal file system, but the contents of the file system can be transparently merged from several sources.
// The "base directory" is the path to the directory holding the quake.exe and all game directories.
// The sys_* files pass this to host_init in quakeparms_t->basedir.
// This can be overridden with the "-basedir" command line parm to allow code debugging in a different directory.
// The base directory is only used during filesystem initialization.
// The "game directory" is the first tree on the search path and directory that all generated files (savegames, screenshots, demos, config files) will be saved to.
// This can be overridden with the "-game" command line parameter.
// The game directory can never be changed while quake is executing.
// This is a precacution against having a malicious server instruct clients to write files over areas they shouldn't.

static int FS_filelength (FILE *f) {
	int		pos;
	int		end;

	pos = ftell (f);
	fseek (f, 0, SEEK_END);
	end = ftell (f);
	fseek (f, pos, SEEK_SET);

	return end;
}

int file_from_pak = 0;

// Finds the file in the search path.
// returns filesize and an open FILE *
// Used for streaming data out of either a pak file or a seperate file.
int FS_FOpenFile (char *filename, FILE **file)
{
	searchpath_t	*search;
	char			netpath[MAX_OSPATH];
	pack_t			*pak;
	int				i;

	file_from_pak = 0;

	// search through the path, one element at a time
	for (search = fs_searchpaths ; search ; search = search->next)
	{
	// is the element a pak file?
		if (search->pack)
		{
			// look through all the pak file elements
			pak = search->pack;
			for (i=0 ; i<pak->numfiles ; i++)
				if (!Q_strcasecmp (pak->files[i].name, filename))
				{	// found it!
					file_from_pak = 1;
					// open a new file on the pakfile
					*file = fopen (pak->filename, "rb");
					assert(*file);
					fseek (*file, pak->files[i].filepos, SEEK_SET);
					return pak->files[i].filelen;
				}
		}
		else
		{
		// check a file in the directory tree

			Com_sprintf (netpath, sizeof(netpath), "%s/%s",search->filename, filename);

			*file = fopen (netpath, "rb");
			if (!*file)
				continue;

			return FS_filelength (*file);
		}

	}

	*file = NULL;
	return -1;
}

// Filename are reletive to the quake search path a null buffer will just return the file length without loading
int FS_LoadFile(char *path, void **buffer) {
	// look for it in the filesystem or pack files
	FILE* h = 0;
	int len = FS_FOpenFile(path, &h);
	int result = len;
	if (h) {
		if (buffer) {
			u8* buf = tml_alloc(len);
			*buffer = buf;
			FS_Read(buf, len, h);
		}
		fclose(h);
	} else {
		if (buffer) {
			*buffer = NULL;
		}
		result = -1;
	}

	return result;
}

void FS_FreeFile(void* buffer) {
	tml_free(buffer);
}

