static int	m_main_cursor;

#define NUM_CURSOR_FRAMES 15

static char *menu_in_sound		= "misc/menu1.wav";
static char *menu_move_sound	= "misc/menu2.wav";
static char *menu_out_sound		= "misc/menu3.wav";

static bool m_entersound; // play after drawing a frame, so caching won't disrupt the sound

typedef char* (*M_Key_Proc)(int k);
typedef void (*M_Draw_Proc)();

static M_Key_Proc m_keyfunc = 0;
static M_Draw_Proc m_drawfunc = 0;

static struct {M_Draw_Proc draw; M_Key_Proc key;} m_layers[8] = {};
static int m_menudepth = 0;

static void M_Banner(char* name) {
	int w = 0;
	int h = 0;
	Draw_GetPicSize(&w, &h, name);
	Draw_Pic(viddef.width / 2 - w / 2, viddef.height / 2 - 110, name);
}

static void M_PushMenu(M_Draw_Proc draw, M_Key_Proc key) {
	// if this menu is already present, drop back to that level to avoid stacking menus by hotkeys
	int i = 0;
	for (; i < m_menudepth; i++) {
		if (m_layers[i].draw == draw && m_layers[i].key == key) {
			m_menudepth = i;
		}
	}

	if (i == m_menudepth) {
		assert(m_menudepth >= 0 && m_menudepth < (int)carray_count(m_layers));

		m_layers[m_menudepth].draw = m_drawfunc;
		m_layers[m_menudepth].key = m_keyfunc;
		m_menudepth++;
	}

	m_drawfunc = draw;
	m_keyfunc = key;

	m_entersound = true;

	cls.key_dest = key_menu;
}

static void M_ForceMenuOff() {
	m_drawfunc = 0;
	m_keyfunc = 0;
	cls.key_dest = key_game;
	m_menudepth = 0;
	Key_ClearStates();
}

static void M_PopMenu() {
	S_StartLocalSound(menu_out_sound);
	assert(m_menudepth >= 1);
	m_menudepth--;

	m_drawfunc = m_layers[m_menudepth].draw;
	m_keyfunc = m_layers[m_menudepth].key;

	if (!m_menudepth) {
		M_ForceMenuOff();
	}
}

static bool Field_Key(menufield_s *field, int key_passed) {
	int key = key_passed;
	switch (key_passed) {
		case K_KP_SLASH: {key = '/';} break;
		case K_KP_MINUS: {key = '-';} break;
		case K_KP_PLUS: {key = '+';} break;
		case K_KP_HOME: {key = '7';} break;
		case K_KP_UPARROW: {key = '8';} break;
		case K_KP_PGUP: {key = '9';} break;
		case K_KP_LEFTARROW: {key = '4';} break;
		case K_KP_5: {key = '5';} break;
		case K_KP_RIGHTARROW: {key = '6';} break;
		case K_KP_END: {key = '1';} break;
		case K_KP_DOWNARROW: {key = '2';} break;
		case K_KP_PGDN: {key = '3';} break;
		case K_KP_INS: {key = '0';} break;
		case K_KP_DEL: {key = '.';} break;
	}

	bool handled = false;
	bool key_is_ascii = key <= 127;
	if (key_is_ascii && key != K_KP_ENTER && key != K_ENTER && key != K_ESCAPE && key != K_TAB) {
		handled = true;

		if ((toupper(key) == 'V' && keydown[K_CTRL]) || ((( key == K_INS) || (key == K_KP_INS)) && keydown[K_SHIFT])) {
			// support pasting from the clipboard
			char* clipboard_data = Sys_GetClipboardData();
			if (clipboard_data) {
				strtok(clipboard_data, "\n\r\b");
				strncpy(field->buffer, clipboard_data, field->length - 1);
				field->cursor = strlen(field->buffer);
				field->visible_offset = max(field->cursor - field->visible_length, 0);
				free(clipboard_data);
			}

		} else {

			switch (key) {
				case K_KP_LEFTARROW:
				case K_LEFTARROW:
				case K_BACKSPACE: {
					if (field->cursor > 0) {
						memmove(&field->buffer[field->cursor-1], &field->buffer[field->cursor], strlen(&field->buffer[field->cursor]) + 1);
						field->cursor--;
						if (field->visible_offset) {
							field->visible_offset--;
						}
					}
				} break;

				case K_KP_DEL:
				case K_DEL: {
					char* dest = field->buffer + field->cursor;
					char* src = dest + 1;
					memmove(dest, src, strlen(src) + 1);
				} break;

				default: {
					if ( !isdigit( key ) && ( field->generic.flags & QMF_NUMBERSONLY ) )
						return false;

					if ( field->cursor < field->length )
					{
						field->buffer[field->cursor++] = key;
						field->buffer[field->cursor] = 0;

						if ( field->cursor > field->visible_length )
						{
							field->visible_offset++;
						}
					}
				} break;
			}

		}
	}

	return handled;
}

static void* item_at_cursor(menuframework_s* menu) {
	void* result = 0;
	if (menu->cursor >= 0 && menu->cursor < menu->nitems) {
		result = menu->items[menu->cursor];
	}
	return result;
}

static void place_cursor_in_nearest_valid_position(menuframework_s* menu, int dir) {
	for (menucommon_s* cursor_item = item_at_cursor(menu); !cursor_item || cursor_item->type == MTYPE_SEPARATOR; cursor_item = item_at_cursor(menu)) {
		menu->cursor += dir;

		// NOTE: wrap
		if (menu->cursor >= menu->nitems) {
			menu->cursor = 0;
		} else if (menu->cursor < 0) {
			menu->cursor = menu->nitems - 1;
		}
	}
}

