static void Menu_SlideItem(menuframework_s *s, int dir) {
	menucommon_s* item = (menucommon_s*)item_at_cursor(s);
	if (item) {
		switch (item->type) {
			case MTYPE_SLIDER: {
				menuslider_s* slider = (menuslider_s*)item;
				slider->curvalue = clamp(slider->curvalue + dir, slider->minvalue, slider->maxvalue);
				if (item->callback) {
					item->callback(item);
				}
			} break;

			case MTYPE_SPINCONTROL: {
				menulist_s* menulist = (menulist_s*)item;
				menulist->curvalue = max(menulist->curvalue + dir, 0);
				if (menulist->itemnames[menulist->curvalue] == 0) {
					menulist->curvalue--;
				}
				if (item->callback) {
					item->callback(item);
				}
			} break;
		}
	}
}

static bool Field_DoEnter(menufield_s* f) {
	if (f->generic.callback) {
		f->generic.callback( f );
		return true;
	}
	return false;
}

static bool Menu_SelectItem( menuframework_s *s ) {
	bool result = false;
	menucommon_s *item = ( menucommon_s * ) item_at_cursor( s );
	if (item) {
		switch ( item->type ) {
			case MTYPE_FIELD: {
				result = Field_DoEnter((menufield_s*)item) ;
			} break;

			case MTYPE_ACTION: {
				Action_DoEnter((menuaction_s*)item);
				result = true;
			}
		}
	}

	return result;
}

static char* Default_MenuKey(menuframework_s* m, int key) {
	bool handled_by_field_key = false;
	if (m) {
		menucommon_s* item = item_at_cursor(m);
		if (item && item->type == MTYPE_FIELD) {
			menufield_s* field = (menufield_s*)item;
			handled_by_field_key = Field_Key(field, key);
		}
	}

	char* sound = 0;
	if (!handled_by_field_key) {
		switch (key) {
			case K_ESCAPE: {
				M_PopMenu();
				sound = menu_out_sound;
			} break;

			case K_KP_UPARROW:
			case K_UPARROW: {
				if (m) {
					m->cursor--;
					place_cursor_in_nearest_valid_position(m, -1);
					sound = menu_move_sound;
				}
			} break;

			case K_TAB: {
				if (m) {
					m->cursor++;
					place_cursor_in_nearest_valid_position(m, 1);
					sound = menu_move_sound;
				}
			} break;

			case K_KP_DOWNARROW:
			case K_DOWNARROW: {
				if (m) {
					m->cursor++;
					place_cursor_in_nearest_valid_position(m, 1);
					sound = menu_move_sound;
				}
			} break;

			case K_KP_LEFTARROW:
			case K_LEFTARROW: {
				if (m) {
					Menu_SlideItem( m, -1 );
					sound = menu_move_sound;
				}
			} break;

			case K_KP_RIGHTARROW:
			case K_RIGHTARROW: {
				if (m) {
					Menu_SlideItem(m, 1);
					sound = menu_move_sound;
				}
			} break;

			case K_MOUSE1:
			case K_MOUSE2:
			case K_MOUSE3:
			case K_KP_ENTER:
			case K_ENTER: {
				if (m) {
					Menu_SelectItem( m );
					sound = menu_move_sound;
				}
			} break;
		}
	}

	return sound;
}

// Draws an animating cursor with the point at x,y.
// The pic will extend to the left of x, and both above and below y.
static void M_DrawCursor( int x, int y, int f )
{
	char	cursorname[80];
	static bool cached;

	if ( !cached )
	{
		int i;

		for ( i = 0; i < NUM_CURSOR_FRAMES; i++ )
		{
			Com_sprintf( cursorname, sizeof( cursorname ), "m_cursor%d", i );

			Draw_FindPic( cursorname );
		}
		cached = true;
	}

	Com_sprintf( cursorname, sizeof(cursorname), "m_cursor%d", f );
	Draw_Pic( x, y, cursorname );
}

static void M_Main_Draw (void)
{
	int i;
	int w, h;
	int ystart;
	int	xoffset;
	int widest = -1;
	char litname[80];
	char *names[] =
	{
		"m_main_game",
		"m_main_options",
		"m_main_video",
		"m_main_quit",
		0
	};

	for ( i = 0; names[i] != 0; i++ )
	{
		Draw_GetPicSize( &w, &h, names[i] );

		if ( w > widest )
			widest = w;
	}

	ystart = ( viddef.height / 2 - 110 );
	xoffset = ( viddef.width - widest + 70 ) / 2;

	for ( i = 0; names[i] != 0; i++ )
	{
		if ( i != m_main_cursor )
			Draw_Pic( xoffset, ystart + i * 40 + 13, names[i] );
	}
	strcpy( litname, names[m_main_cursor] );
	strcat( litname, "_sel" );
	Draw_Pic( xoffset, ystart + m_main_cursor * 40 + 13, litname );

	M_DrawCursor( xoffset - 25, ystart + m_main_cursor * 40 + 11, (int)(cls.realtime / 100)%NUM_CURSOR_FRAMES );

	Draw_GetPicSize( &w, &h, "m_main_plaque" );
	Draw_Pic( xoffset - 30 - w, ystart, "m_main_plaque" );

	Draw_Pic( xoffset - 30 - w, ystart + h + 5, "m_main_logo" );
}

