	COM_SetValueCvar("freelook", clamp(freelook->value, 0, 1));
	s_options_freelook_box.curvalue = freelook->value;

	COM_SetValueCvar("crosshair", clamp(crosshair->value, 0, 3));
	s_options_crosshair_box.curvalue = crosshair->value;
