static char* M_Quit_Key(int key) {
	switch (key){
		case K_ESCAPE:
		case 'n':
		case 'N': {M_PopMenu();} break;

		case 'Y':
		case 'y': {context.exit_process();} break;
	}

	return NULL;
}

