{
	if (!ent->message)
	{
		G_FreeEdict (ent);
		return;
	}
	ent->use = Use_Target_Help;
}

// Counts a secret found.
// These are single use targets.
static void use_target_secret(edict_t *ent, edict_t* other, edict_t* activator)
{
	UNUSED(other);

	PF_StartSound (ent, CHAN_VOICE, ent->noise_index, 1, ATTN_NORM, 0);

	level.found_secrets++;

	G_UseTargets (ent, activator);
	G_FreeEdict (ent);
}

void SP_target_secret (edict_t *ent)
{
	ent->use = use_target_secret;
	if (!st.noise)
		st.noise = "misc/secret.wav";
	ent->noise_index = SV_SoundIndex (st.noise);
	ent->svflags = SVF_NOCLIENT;
	level.total_secrets++;
	// map bug hack
	if (!Q_stricmp(level.mapname, "mine3") && ent->s.origin[0] == 280 && ent->s.origin[1] == -2048 && ent->s.origin[2] == -624)
		ent->message = "You have found a secret area.";
}

// Counts a goal completed.
// These are single use targets.
static void use_target_goal(edict_t *ent, edict_t* other, edict_t* activator)
{
	UNUSED(other);

	PF_StartSound (ent, CHAN_VOICE, ent->noise_index, 1, ATTN_NORM, 0);

	level.found_goals++;

	if (level.found_goals == level.total_goals)
		PF_Configstring (CS_CDTRACK, "0");

	G_UseTargets (ent, activator);
	G_FreeEdict (ent);
}

void SP_target_goal (edict_t *ent)
{
	ent->use = use_target_goal;
	if (!st.noise)
		st.noise = "misc/secret.wav";
	ent->noise_index = SV_SoundIndex (st.noise);
	ent->svflags = SVF_NOCLIENT;
	level.total_goals++;
}

