static void GL_Bind(int texnum) {
	if (gl_state.currenttexture != texnum) {
		gl_state.currenttexture = texnum;
		glBindTexture(GL_TEXTURE_2D, texnum);
	}
}

// Draws one 8x8 graphics character with 0 being transparent.
// It can be clipped to the top of the screen to allow the console to be smoothly scrolled off.
void Draw_Char(int x, int y, int num) {
	int				row, col;
	float			frow, fcol, size;

	num &= 255;

	if ( (num & 127) == 32 )
		return; // space

	if (y <= -8)
		return; // totally off screen

	row = num >> 4;
	col = num & 15;

	frow = row * 0.0625;
	fcol = col * 0.0625;
	size = 0.0625;

	GL_Bind(draw_chars->texnum);

	glBegin(GL_QUADS);
	glTexCoord2f(fcol, frow);
	glVertex2f(x, y);
	glTexCoord2f(fcol + size, frow);
	glVertex2f(x + 8, y);
	glTexCoord2f(fcol + size, frow + size);
	glVertex2f(x + 8, y + 8);
	glTexCoord2f(fcol, frow + size);
	glVertex2f(x, y + 8);
	glEnd();
}

// Finds or loads the given image
static image_t* GL_FindImage(char* name, imagetype_t type) {
	image_t* target_image = 0;

	String name_str = string_from_cstring(name);
	if (name_str.ptr && name_str.len >= 5) {

		// look for it first
		for (i64 ind = 0; !target_image && ind < numgltextures; ind++) {
			image_t* image = gltextures + ind;
			if (!strcmp(name, image->name)) {
				image->registration_sequence = registration_sequence;
				target_image = image;
			}
		}

		// Then load
		if (!target_image) {
			bool is_pcx = string_ends_with(name_str, STR(".pcx"));
			bool is_wal = string_ends_with(name_str, STR(".wal"));
			bool is_tga = string_ends_with(name_str, STR(".tga"));
			if (is_pcx || is_wal || is_tga) {
				Texture texture = context.load_texture(name_str);
				imagetype_t actual_type = is_wal ? it_wall : type;
				int bits = is_tga ? 32 : 8;
				target_image = GL_LoadPic(name, texture.pixels, texture.width, texture.height, actual_type, bits);
			}
		}
	}

	return target_image;
}

image_t	*Draw_FindPic (char *name)
{
	image_t *gl;
	char	fullname[MAX_QPATH];

	if (name[0] != '/' && name[0] != '\\')
	{
		Com_sprintf (fullname, sizeof(fullname), "pics/%s.pcx", name);
		gl = GL_FindImage (fullname, it_pic);
	}
	else
		gl = GL_FindImage (name+1, it_pic);

	return gl;
}

/*
=============
Draw_GetPicSize
=============
*/
void Draw_GetPicSize (int *w, int *h, char *pic)
{
	image_t *gl;

	gl = Draw_FindPic (pic);
	if (!gl)
	{
		*w = *h = -1;
		return;
	}
	*w = gl->width;
	*h = gl->height;
}

void Draw_StretchPic (int x, int y, int w, int h, char *pic)
{
	image_t *gl;

	gl = Draw_FindPic (pic);
	if (!gl)
	{
		Com_Printf("Can't find pic: %s\n", pic);
		return;
	}

	if (scrap_dirty)
		Scrap_Upload ();

	GL_Bind (gl->texnum);
	glBegin (GL_QUADS);
	glTexCoord2f (gl->sl, gl->tl);
	glVertex2f (x, y);
	glTexCoord2f (gl->sh, gl->tl);
	glVertex2f (x+w, y);
	glTexCoord2f (gl->sh, gl->th);
	glVertex2f (x+w, y+h);
	glTexCoord2f (gl->sl, gl->th);
	glVertex2f (x, y+h);
	glEnd ();
}

void Draw_Pic (int x, int y, char *pic)
{
	image_t *gl;

	gl = Draw_FindPic (pic);
	if (!gl)
	{
		Com_Printf("Can't find pic: %s\n", pic);
		return;
	}
	if (scrap_dirty)
		Scrap_Upload ();

	GL_Bind (gl->texnum);
	glBegin (GL_QUADS);
	glTexCoord2f (gl->sl, gl->tl);
	glVertex2f (x, y);
	glTexCoord2f (gl->sh, gl->tl);
	glVertex2f (x+gl->width, y);
	glTexCoord2f (gl->sh, gl->th);
	glVertex2f (x+gl->width, y+gl->height);
	glTexCoord2f (gl->sl, gl->th);
	glVertex2f (x, y+gl->height);
	glEnd ();
}

// Fills a box of pixels with a single color
void Draw_Fill (int x, int y, int w, int h, int c)
{
	union
	{
		unsigned	c;
		u8		v[4];
	} color;

	assert((unsigned)c <= 255);

	glDisable (GL_TEXTURE_2D);

	color.c = d_8to24table[c];
	glColor3f (color.v[0]/255.0,
		color.v[1]/255.0,
		color.v[2]/255.0);

	glBegin (GL_QUADS);

	glVertex2f (x,y);
	glVertex2f (x+w, y);
	glVertex2f (x+w, y+h);
	glVertex2f (x, y+h);

	glEnd ();
	glColor3f (1,1,1);
	glEnable (GL_TEXTURE_2D);
}

void Draw_FadeScreen (void)
{
	glEnable (GL_BLEND);
	glDisable (GL_TEXTURE_2D);
	glColor4f (0, 0, 0, 0.8);
	glBegin (GL_QUADS);

	glVertex2f (0,0);
	glVertex2f (viddef.width, 0);
	glVertex2f (viddef.width, viddef.height);
	glVertex2f (0, viddef.height);

	glEnd ();
	glColor4f (1,1,1,1);
	glEnable (GL_TEXTURE_2D);
	glDisable (GL_BLEND);
}

