static void GL_TexEnv(GLenum mode) {
	static int lastmode = -1;
	if ((int)mode != lastmode) {
		glTexEnvf(GL_TEXTURE_ENV, GL_TEXTURE_ENV_MODE, mode);
		lastmode = mode;
	}
}

