	// draw the banner
	int w = 0;
	int h = 0;
	Draw_GetPicSize(&w, &h, "m_banner_video");
	Draw_Pic(viddef.width/2 - w/2, viddef.height/2 - 110, "m_banner_video");

	// move cursor to a reasonable starting position
	place_cursor_in_nearest_valid_position(&s_opengl_menu, 1);

